document.addEventListener("DOMContentLoaded",function(){null!==document.querySelector(".p-content-slide")&&document.querySelectorAll(".p-content-slide").forEach(function(e){var t,n,o,c;n=(t=e).querySelector(".p-content-slide__slides"),o=t.querySelector(".controller-next"),c=t.querySelector(".controller-prev"),o.addEventListener("click",function(){n.scrollLeft+=n.offsetWidth}),c.addEventListener("click",function(){n.scrollLeft-=n.offsetWidth})})},!1);